<a class="back-link" href="/admin/products">← Retour aux produits</a><div class="admin-title"><div><span class="eyebrow">CATALOGUE</span><h1><?= e($title) ?></h1></div></div><section class="panel form-panel"><?php if(isset($error)): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif; ?><form action="/admin/products<?= !empty($product['id'])?'/'.(int)$product['id']:'' ?>" method="post"><?= csrf_field() ?><label for="name">Nom du produit</label><input id="name" name="name" value="<?= e($product['name'] ?? '') ?>" minlength="3" maxlength="120" required><label for="description">Description</label><textarea id="description" name="description" rows="4" minlength="10" maxlength="2000" required><?= e($product['description'] ?? '') ?></textarea><div class="form-grid"><div><label for="price">Prix en euros</label><input id="price" name="price" inputmode="decimal" value="<?= e($product['price_raw'] ?? (isset($product['price_cents'])?number_format((int)$product['price_cents']/100,2,'.',''):'')) ?>" placeholder="29.00" required></div><div><label for="stock">Stock disponible</label><input id="stock" name="stock" type="number" min="0" max="10000" value="<?= (int)($product['stock'] ?? 0) ?>" required></div><div><label for="category">Catégorie</label><select id="category" name="category_id"><?php foreach ($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= selected($product['category_id'] ?? '',$c['id']) ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div><label for="illustration">Illustration</label><select id="illustration" name="illustration"><?php foreach (['keyboard'=>'Clavier','lamp'=>'Lampe','bottle'=>'Gourde','notebook'=>'Carnet','headphones'=>'Casque','bag'=>'Sac','stand'=>'Support','mouse'=>'Souris'] as $v=>$l): ?><option value="<?= $v ?>" <?= selected($product['illustration'] ?? '',$v) ?>><?= $l ?></option><?php endforeach; ?></select></div></div><div class="form-actions"><a class="button secondary" href="/admin/products">Annuler</a><button class="button">Enregistrer le produit <?= icon('check') ?></button></div></form></section>
